package org.kanger.storage.dumb2;
import java.util.*;import java.nio.file.*;import org.kanger.*;import org.kanger.storage.dumb2.ContextNativeCandidateLeaseMatrix.Fixture;
public final class ContextGeneralArgumentsPublicationRunner {
 static int checks;static void require(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}static String tuple(String p,List<String> a){return p+"("+String.join(",",a)+")";}
 public static void main(String[] args){try{Path d=Files.createTempDirectory("general-argument-write-");System.setProperty("user.home",d.toString());List<String> vars=new ArrayList<>(),values=new ArrayList<>();StringBuilder prefix=new StringBuilder("!");for(int i=0;i<17;i++){vars.add("v"+i);values.add(Integer.toString(i+1));prefix.append("@v").append(i).append(' ');}List<String> backwards=new ArrayList<>(vars);Collections.reverse(backwards);String rule=prefix+tuple("wide",vars)+"->"+tuple("out",backwards)+";";List<String> reversed=new ArrayList<>(values);Collections.reverse(reversed);
  ContextNativeCandidateLeaseMatrix.create(d,"Wide","!"+tuple("wide",values)+";");ContextNativeCandidateLeaseMatrix.create(d,"Opposition","!~"+tuple("out",reversed)+";");
  try(Fixture f=new Fixture(d,"Refuted")){f.db.connectContext("Wide");f.db.connectContext("Opposition");long before=f.db.getRevision();ContextSignedModelPublication no=f.db.publishSignedModelCandidate(f.mind,new ContextSignedModelRequest(rule,Collections.emptyMap()));require(no.status==ContextSignedModelPublication.Status.REFUTED&&no.evidence!=null,"17-argument/17-variable proof before limited positive model search: "+no.phase+" "+no.reason);require(no.evidence.getOppositions().stream().anyMatch(o->o.sources.size()==3),"exact three original Sources, no projected tuple facts");no.evidence.check(64000000,64);require(ContextNativeCommitGuardMatrix.primary(f).isEmpty()&&f.db.getRevision()==before,"general tuple refutation atomic");}
  try(Fixture f=new Fixture(d,"PositiveStillLimited")){long before=f.db.getRevision();ContextSignedModelPublication no=f.db.publishSignedModelCandidate(f.mind,new ContextSignedModelRequest(rule,Collections.emptyMap()));require(no.status==ContextSignedModelPublication.Status.PUBLISHED,"actual general relational model now authorizes complete tuple rule");require(ContextNativeCommitGuardMatrix.primary(f).equals(Collections.singleton(rule))&&f.db.getRevision()>before,"accepted whole tuple rule only, no model facts");}
  try(Fixture f=new Fixture(d,"Budget")){long before=f.db.getRevision();ContextSignedModelPublication no=f.db.publishSignedModelCandidate(f.mind,new ContextSignedModelRequest(rule,Collections.singletonMap("work",1)));require(no.status==ContextSignedModelPublication.Status.INCOMPLETE,"resource exhaustion is not contradiction");require(ContextNativeCommitGuardMatrix.primary(f).isEmpty()&&f.db.getRevision()==before,"bounded failure atomic");}
  System.out.println("GENERAL_ARGUMENT_PUBLICATION highArityNegativeProof=true exactSources=true positiveRelationalModelPublished=true noDefaultActivation=true atomicResourceFailure=true");System.out.println("CONTEXT_GENERAL_ARGUMENT_PUBLICATION_PASS checks="+checks);System.exit(0);
 }catch(Throwable t){t.printStackTrace();System.exit(1);}}
}
